{
  "analysis": "We have OCR for all 380 prompt-line crops, but the parser output was only partially visible. To accurately reconstruct the full 262-move command list, I need save and inspect the complete grouped prompt data, and also cross-check with full-screen OCR and the move counter. The current 2 fps prompt OCR captures typing fragments but may miss fast submissions, so I need validate coverage.",
  "plan": "Save the prompt grouping parser output to a file for full inspection, check how far the partial full-screen OCR progressed, and extract/OCR the top status line (score/moves) from all frames to validate move count changes. This will help ensure the reconstructed command list is complete.",
  "commands": [
    {
      "keystrokes": "python3 - <<'PY' > /app/prompt_groups.txt
import re
lines=open('/app/prompt_ocr.txt').read().splitlines()
ents=[]
for i,l in enumerate(lines,1):
    m=re.match(r'(\d+)\s+(.*)', l)
    if not m: continue
    fr=int(m.group(1)); txt=m.group(2).strip()
    ents.append((fr,txt))
def clean(t):
    t=t.replace('_','').strip()
    if t.startswith('>'): t=t[1:].strip()
    return t.strip()
groups=[]
cur=[]
lastfr=None
for fr,txt in ents:
    if txt.startswith('>') and re.search(r'[A-Za-z]', txt):
        if cur and lastfr is not None and fr-lastfr>3:
            groups.append(cur); cur=[]
        cur.append((fr,txt,clean(txt)))
        lastfr=fr
    else:
        if cur:
            groups.append(cur); cur=[]
        lastfr=fr
if cur: groups.append(cur)
print('groups',len(groups))
for g in groups:
    frs=[x[0] for x in g]
    longest=max(g,key=lambda x:len(x[2]))
    print(f'[{frs[0]:04d}-{frs[-1]:04d}] candidate={longest[2]!r}')
    print('   '+' | '.join(f'{fr}:{c!r}' for fr,raw,c in g))
PY
",
      "duration": 0.1
    },
    {
      "keystrokes": "grep '^===' /app/dense_ocr.txt | tail -5; wc -l /app/prompt_groups.txt
",
      "duration": 0.1
    },
    {
      "keystrokes": "sed -n '1,220p' /app/prompt_groups.txt
",
      "duration": 0.1
    }
  ]
}
